  messageTemplate = messageTemplate.replace('%=avatarClass%=', avatarClass || '');
  messageTemplate = messageTemplate.replace('%=messageClass%=', messageClass || '');
  messageTemplate = messageTemplate.replace('%=timestampClass%=', timestampClass || '');
  messageTemplate = messageTemplate.replace('%=messageText%=', messageText);
  messageTemplate = messageTemplate.replace('%=timestamp%=', getRandomTimestamp());

  return $(messageTemplate);
}

// Generate a chat message
function addChatMessage(messageText, isUser) {
  const className = isUser ? 'user' : 'bot';
  const avatarClass = isUser ? 'chat-avatar bg-blue' : 'chat-avatar bg-red';
  const messageClass = isUser ? 'text-dark' : 'text-white';
  const timestampClass = 'text-muted';

  const chatMessageElement = createChatMessageElement(messageText, className, avatarClass, messageClass, timestampClass);
  chatContainer.append(chatMessageElement);
}

// Generate the chat history
function generateChatHistory() {
  addChatMessage('Привет, это имитация чат-бота!', false);
  addChatMessage('Как дела?', false);
  addChatMessage('Мой ответ: отлично!', true);
  addChatMessage('Какая погода в твоей местности?', false);
}

// Open the modal with chat history
function openChatModal() {
  chatModal.modal('show');
  generateChatHistory();
}

// Close the modal
function closeChatModal() {
  chatModal.modal('hide');
}

// Initialize the chat modal
$(function () {
  $('#chat-modal-btn').click(openChatModal);
  chatModal.on('hidden.bs.modal', closeChatModal);
});
```

В данном коде мы объявляем функции для создания элементов чата, генерации случайных timestamp'ов, создания шаблонов сообщений, добавления сообщений в контейнер чата, генерации истории чата и открытия/закрытия модального окна.

